#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;

    vector<ll> a(n);
    for (ll &x : a) cin >> x;
    sort(a.begin(), a.end());

    vector<unordered_map<ll, int>> costs(n);

    for (int i = 0; i < n; ++i) {
        ll x = a[i] / 2;
        int operations = 1;

        while (x > 0) {
            costs[i].emplace(x, operations);
            x /= 2;
            ++operations;
        }
        costs[i].emplace(0, operations);
    }

    ll answer = LLONG_MAX;
    ll limit = a[n - k];

    for (ll target = limit;; --target) {
        int count = 0;
        ll total = 0;
        int start = lower_bound(a.begin(), a.end(), target) - a.begin();

        for (int i = start; i < n; ++i) {
            if (a[i] == target) {
                ++count;
            } else {
                auto it = costs[i].find(target);
                if (it != costs[i].end()) {
                    ++count;
                    total += it->second;
                }
            }

            if (count == k) {
                answer = min(answer, total);
                break;
            }
        }

        if (target == 0) break;
    }

    cout << answer;
    return 0;
}

