        for (ll l = j; l < n; ++l) {
            if (a[l] == target) {
                ++count;
            } else {
                auto it = v[l].find(target);
                if (it != v[l].end()) {
                    ++count;
                    operations += it->second;
                }
            }

            if (count == k) {
                ans = min(ans, operations);
                break;
            }
        }
    }

    cout << ans;
    return 0;
}

